import heapq

def k_smallest_pairs(nums1, nums2, k):
    if not nums1 or not nums2 or k == 0:
        return []

    min_heap = []
    for i in range(min(k, len(nums1))):
        for j in range(min(k, len(nums2))):
            if len(min_heap) < k:
                heapq.heappush(min_heap, (-(nums1[i] + nums2[j]), [nums1[i], nums2[j]]))
            else:
                # If the current smallest pair is less than the largest in the heap, replace it
                if nums1[i] + nums2[j] > -min_heap[0][0]:
                    heapq.heappushpop(min_heap, (-(nums1[i] + nums2[j]), [nums1[i], nums2[j]]))

    # Extract the pairs from the heap and reverse to get them in ascending order
    return [pair[1] for pair in sorted(min_heap, reverse=True)]

